import json

class Message:
    def __init__(self, message_id: str, payload: dict, attributes: dict = None):
        self.message_id = message_id
        self.payload = payload
        self.attributes = attributes if attributes is not None else {}

    def to_json(self):
        return json.dumps({
            "message_id": self.message_id,
            "payload": self.payload,
            "attributes": self.attributes
        })

    @classmethod
    def from_sqs_message(cls, sqs_message):
        body = json.loads(sqs_message['Body'])
        # Assuming SNS message structure within SQS
        if 'Message' in body and 'MessageId' in body:
            message_id = body['MessageId']
            payload = json.loads(body['Message'])
            attributes = body.get('MessageAttributes', {})
            return cls(message_id, payload, attributes)
        # Direct SQS message
        else:
            message_id = sqs_message['MessageId']
            payload = json.loads(sqs_message['Body'])
            attributes = sqs_message.get('MessageAttributes', {})
            return cls(message_id, payload, attributes)

class PublishRequest:
    def __init__(self, event: dict, attributes: dict = None):
        self.event = event
        self.attributes = attributes if attributes is not None else {}

class PublishResponse:
    def __init__(self, message_id: str):
        self.message_id = message_id

class ConsumeResponse:
    def __init__(self, message: Message, receipt_handle: str):
        self.message = message
        self.receipt_handle = receipt_handle

import boto3


class MessagingClient:
    def __init__(self, region_name: str, topic_arn: str = None, queue_url: str = None, dead_letter_queue_url: str = None):
        self.region_name = region_name
        self.topic_arn = topic_arn
        self.queue_url = queue_url
        self.dead_letter_queue_url = dead_letter_queue_url
        self.sns_client = boto3.client("sns", region_name=self.region_name)
        self.sqs_client = boto3.client("sqs", region_name=self.region_name)

    def get_sns_client(self):
        return self.sns_client

    def get_sqs_client(self):
        return self.sqs_client

import os
import json

from messaging_client import MessagingClient
from messaging_models import Message

def dead_letter_event(message: Message, receipt_handle: str, config=None):
    config = config or {}
    region_name = config.get("region", os.environ.get("AWS_REGION", "us-east-1"))
    queue_url = config.get("queue_url", os.environ.get("SQS_QUEUE_URL")) # Original queue URL
    dead_letter_queue_url = config.get("dead_letter_queue_url", os.environ.get("SQS_DEAD_LETTER_QUEUE_URL"))

    if not dead_letter_queue_url:
        raise ValueError("SQS_DEAD_LETTER_QUEUE_URL must be provided in config or environment variables.")

    messaging_client = MessagingClient(region_name=region_name, dead_letter_queue_url=dead_letter_queue_url)
    sqs_client = messaging_client.get_sqs_client()

    # Optionally delete from original queue if processing failed after consumption but before DLQing
    if queue_url and receipt_handle:
        sqs_client.delete_message(
            QueueUrl=queue_url,
            ReceiptHandle=receipt_handle
        )

    response = sqs_client.send_message(
        QueueUrl=dead_letter_queue_url,
        MessageBody=message.to_json(),
        MessageAttributes={
            'MessageType': {
                'DataType': 'String',
                'StringValue': 'DeadLetterMessage'
            }
        }
    )
    return {"message_id": response["MessageId"]}

import json
import os

import boto3

from messaging_client import MessagingClient
from messaging_models import PublishRequest

def batch_publish_events(publish_requests: list[PublishRequest], config=None):
    config = config or {}
    region_name = config.get("region", os.environ.get("AWS_REGION", "us-east-1"))
    topic_arn = config.get("topic_arn", os.environ.get("SNS_TOPIC_ARN"))

    if not topic_arn:
        raise ValueError("SNS_TOPIC_ARN must be provided in config or environment variables.")

    messaging_client = MessagingClient(region_name=region_name, topic_arn=topic_arn)
    sns_client = messaging_client.get_sns_client()

    entries = []
    for i, req in enumerate(publish_requests):
        entry = {
            'Id': str(i),
            'Message': json.dumps(req.event),
        }
        if req.attributes:
            message_attributes = {}
            for key, value in req.attributes.items():
                # AWS SNS MessageAttributes require specific format
                message_attributes[key] = {'DataType': 'String', 'StringValue': str(value)}
            entry['MessageAttributes'] = message_attributes
        entries.append(entry)

    response = sns_client.publish_batch(
        TopicArn=topic_arn,
        PublishBatchRequestEntries=entries
    )

    successful_messages = [{'id': msg['Id'], 'message_id': msg['MessageId']} for msg in response.get('Successful', [])]
    failed_messages = response.get('Failed', [])

    return {
        "successful": successful_messages,
        "failed": failed_messages
    }
